// ── Activity Selection — maximum non-overlapping intervals ─────
// Greedy: always pick the activity with the earliest finish time.
// Sort by end time, then greedily select if start >= last end.
//
// Time: O(n log n) for sort, O(n) for selection — total O(n log n)
// Space: O(n) for result (O(1) extra beyond input)

function activitySelection(activities) {
  // activities = [{start, end, name}, ...]
  const sorted = [...activities].sort((a, b) => a.end - b.end);
  const selected = [sorted[0]];
  let lastEnd = sorted[0].end;

  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i].start >= lastEnd) {
      selected.push(sorted[i]);
      lastEnd = sorted[i].end;
    }
  }
  return selected;
}

const activities = [
  { start: 1,  end: 4,  name: 'A' },
  { start: 3,  end: 5,  name: 'B' },
  { start: 0,  end: 6,  name: 'C' },
  { start: 5,  end: 7,  name: 'D' },
  { start: 3,  end: 9,  name: 'E' },
  { start: 5,  end: 9,  name: 'F' },
  { start: 6,  end: 10, name: 'G' },
  { start: 8,  end: 11, name: 'H' },
];
console.log(activitySelection(activities).map(a => a.name)); // ["A", "D", "H"]

// ── Greedy coin change (ONLY works for canonical denominations) ─
// Fails for arbitrary denominations — use DP instead.
function greedyCoinChange(coins, amount) {
  const sorted = [...coins].sort((a, b) => b - a); // descending
  const used = [];
  for (const coin of sorted) {
    while (amount >= coin) {
      used.push(coin);
      amount -= coin;
    }
  }
  return amount === 0 ? used : null; // null if impossible
}

console.log(greedyCoinChange([1, 5, 10, 25], 36)); // [25, 10, 1]
console.log(greedyCoinChange([1, 3, 4], 6));        // [4, 1, 1] — WRONG: optimal is [3, 3]

// ── Huffman Encoding — greedy optimal prefix-free code ─────────
// Uses a min-heap (priority queue). Merge the two lowest-frequency
// nodes repeatedly until one root remains.
//
// Time: O(n log n)  Space: O(n)

class MinHeap {
  constructor() { this.data = []; }
  push(node) {
    this.data.push(node);
    this.data.sort((a, b) => a.freq - b.freq); // simplified; use proper heap in prod
  }
  pop() { return this.data.shift(); }
  get size() { return this.data.length; }
}

function buildHuffmanTree(freqMap) {
  const heap = new MinHeap();
  for (const [char, freq] of Object.entries(freqMap)) {
    heap.push({ char, freq, left: null, right: null });
  }
  while (heap.size > 1) {
    const left  = heap.pop(); // lowest frequency
    const right = heap.pop(); // second lowest
    heap.push({ char: null, freq: left.freq + right.freq, left, right });
  }
  return heap.pop(); // root of Huffman tree
}

function getCodes(node, prefix = '', codes = {}) {
  if (!node.left && !node.right) { codes[node.char] = prefix || '0'; return codes; }
  if (node.left)  getCodes(node.left,  prefix + '0', codes);
  if (node.right) getCodes(node.right, prefix + '1', codes);
  return codes;
}

const freqs = { a: 45, b: 13, c: 12, d: 16, e: 9, f: 5 };
const tree  = buildHuffmanTree(freqs);
console.log(getCodes(tree));
// { a: '0', b: '101', c: '100', d: '111', e: '1101', f: '1100' }

